const { createHmac } = require('crypto');
const secret = $env.CONVEX_INBOUND_SECRET;
const baseUrl = $env.CONVEX_SITE_URL;
if (!secret || !baseUrl) throw new Error('Configure CONVEX_INBOUND_SECRET and CONVEX_SITE_URL');
const rawBody = '{}';
const timestamp = String(Math.floor(Date.now() / 1000));
const signature = 'sha256=' + createHmac('sha256', secret).update(timestamp + '.' + rawBody).digest('hex');
return [{json:{url:baseUrl.replace(/\/+$/, '') + '/n8n/overdue',rawBody,timestamp,signature}}];

const response = $input.first().json;
if (!Array.isArray(response.loans)) throw new Error('Invalid overdue response: expected loans array');
const seen = new Set();
const items = [];
for (const loan of response.loans) {
  if (!loan || typeof loan !== 'object' || typeof loan.alreadyReminded !== 'boolean') throw new Error('Invalid overdue loan');
  for (const field of ['loanId','borrowerName','borrowerEmail','toolName','endDate','reminderKey']) {
    if (typeof loan[field] !== 'string' || !loan[field]) throw new Error('Invalid overdue loan fields');
  }
  // Idempotent writebacks make completed reruns skip today's prior deliveries.
  if (loan.alreadyReminded || seen.has(loan.reminderKey)) continue;
  seen.add(loan.reminderKey);
  items.push({json:{loanId:loan.loanId,borrowerName:loan.borrowerName,borrowerEmail:loan.borrowerEmail,toolName:loan.toolName,endDate:loan.endDate,reminderKey:loan.reminderKey},pairedItem:{item:0}});
}
return items;

return $input.all().map((item, index) => {
  const loan = item.json;
  // MOCK ONLY. A real provider must deduplicate on reminderKey before sending.
  const message = loan.borrowerName + ', please return ' + loan.toolName + '. It was due ' + loan.endDate + '.';
  console.log(JSON.stringify({channel:'mock',kind:'overdue_reminder',loanId:loan.loanId,idempotencyKey:loan.reminderKey}));
  // A message is built for the real-provider replacement but no contact/body is logged.
  void message;
  return {json:{loanId:loan.loanId,reminderKey:loan.reminderKey,mock:true},pairedItem:{item:index}};
});

const { createHmac } = require('crypto');
const secret = $env.CONVEX_INBOUND_SECRET;
const baseUrl = $env.CONVEX_SITE_URL;
if (!secret || !baseUrl) throw new Error('Configure CONVEX_INBOUND_SECRET and CONVEX_SITE_URL');
return $input.all().map((item, index) => {
  const loan = item.json;
  const rawBody = JSON.stringify({loanId:loan.loanId,kind:'overdue_reminder',status:'sent',idempotencyKey:loan.reminderKey,detail:'Mock overdue reminder logged by n8n'});
  const timestamp = String(Math.floor(Date.now() / 1000));
  const signature = 'sha256=' + createHmac('sha256', secret).update(timestamp + '.' + rawBody).digest('hex');
  return {json:{url:baseUrl.replace(/\/+$/, '') + '/n8n/events',rawBody,timestamp,signature},pairedItem:{item:index}};
});
